SELECT *
FROM t_work_daily_report_item
WHERE work_daily_report_id = #{workDailyReportId}
AND work_daily_report_item_id IN

    #{item}

SELECT t_work_daily_report_item.work_item_type_id, t_work_daily_report_item.work_item_type_name, COUNT(t_work_daily_report_item.work_daily_report_item_id) AS item_count, IFNULL(SUM(t_work_daily_report_item.final_score), 0) AS total_score FROM t_work_daily_report INNER JOIN t_work_daily_report_item ON t_work_daily_report.work_daily_report_id = t_work_daily_report_item.work_daily_report_id
t_work_daily_report.status = #{auditPassStatus} AND t_work_daily_report.report_date = #{queryForm.reportDate}
AND t_work_daily_report.employee_id = #{queryForm.employeeId}
AND t_work_daily_report.employee_id IN
#{item}
GROUP BY t_work_daily_report_item.work_item_type_id, t_work_daily_report_item.work_item_type_name ORDER BY total_score DESC, t_work_daily_report_item.work_item_type_id ASC

SELECT t_work_daily_report.report_date, t_work_daily_report_item.work_item_id, t_work_daily_report_item.work_item_name, t_work_daily_report_item.work_item_type_id, t_work_daily_report_item.work_item_type_name, t_work_daily_report_item.standard_score, t_work_daily_report_item.final_score, t_work_daily_report_item.deduct_reason, t_work_daily_report_item.finish_remark FROM t_work_daily_report INNER JOIN t_work_daily_report_item ON t_work_daily_report.work_daily_report_id = t_work_daily_report_item.work_daily_report_id
t_work_daily_report.status = #{auditPassStatus} AND t_work_daily_report.report_date = #{queryForm.reportDate}
AND t_work_daily_report.employee_id = #{queryForm.employeeId}
AND t_work_daily_report.employee_id IN
#{item}
AND t_work_daily_report_item.work_item_type_id = #{queryForm.workItemTypeId}
ORDER BY t_work_daily_report_item.sort ASC, t_work_daily_report_item.work_daily_report_item_id ASC
